import React, { useState, useEffect } from 'react';
import Sidebar from '../components/Sidebar';
import Header from '../components/Header';
import api from '../services/api';
import { Users, GraduationCap, Activity, TrendingUp, Search, Bell } from 'lucide-react';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell
} from 'recharts';

const Dashboard = () => {
  const [statistics, setStatistics] = useState({ students: 0, faculty: 0, active: 0, total: 0 });
  const [popularSearches, setPopularSearches] = useState([]);
  const [recentNotifications, setRecentNotifications] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [statsRes, popularRes, notificationsRes] = await Promise.all([
        api.get('/statistics'),
        api.get('/search/popular?limit=5'),
        api.get('/notifications?limit=5')
      ]);
      
      setStatistics(statsRes.data);
      setPopularSearches(popularRes.data.popular_searches);
      setRecentNotifications(notificationsRes.data);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const statsCards = [
    {
      title: 'Total Students',
      value: statistics.students,
      icon: Users,
      color: 'bg-blue-500',
      trend: '+12%'
    },
    {
      title: 'Total Faculty',
      value: statistics.faculty,
      icon: GraduationCap,
      color: 'bg-green-500',
      trend: '+5%'
    },
    {
      title: 'Active Records',
      value: statistics.active,
      icon: Activity,
      color: 'bg-purple-500',
      trend: '+8%'
    },
    {
      title: 'Searches Today',
      value: '1,234',
      icon: Search,
      color: 'bg-orange-500',
      trend: '+23%'
    }
  ];

  const searchData = [
    { month: 'Jan', searches: 400 },
    { month: 'Feb', searches: 600 },
    { month: 'Mar', searches: 800 },
    { month: 'Apr', searches: 750 },
    { month: 'May', searches: 900 },
    { month: 'Jun', searches: 1100 }
  ];

  const departmentData = [
    { name: 'Computer Science', value: 450 },
    { name: 'Engineering', value: 380 },
    { name: 'Business', value: 320 },
    { name: 'Medicine', value: 290 },
    { name: 'Arts', value: 210 }
  ];

  const COLORS = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6'];

  if (loading) {
    return (
      <div className="flex">
        <Sidebar />
        <div className="ml-64 flex-1">
          <Header />
          <div className="p-8 flex items-center justify-center h-96">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
              <p className="mt-4 text-gray-600">Loading dashboard...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex">
      <Sidebar />
      <div className="ml-64 flex-1">
        <Header />
        
        <div className="p-8 mt-16">
          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            {statsCards.map((stat, index) => {
              const Icon = stat.icon;
              return (
                <div key={index} className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
                  <div className="flex items-center justify-between mb-4">
                    <div className={`${stat.color} p-3 rounded-lg`}>
                      <Icon className="text-white" size={24} />
                    </div>
                    <span className="text-green-600 text-sm font-semibold">{stat.trend}</span>
                  </div>
                  <h3 className="text-gray-500 text-sm mb-1">{stat.title}</h3>
                  <p className="text-3xl font-bold text-gray-800">{stat.value.toLocaleString()}</p>
                </div>
              );
            })}
          </div>
          
          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h3 className="text-lg font-semibold text-gray-800 mb-4">Search Trends</h3>
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={searchData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="month" />
                  <YAxis />
                  <Tooltip />
                  <Legend />
                  <Line type="monotone" dataKey="searches" stroke="#3B82F6" strokeWidth={2} />
                </LineChart>
              </ResponsiveContainer>
            </div>
            
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h3 className="text-lg font-semibold text-gray-800 mb-4">Department Distribution</h3>
              <ResponsiveContainer width="100%" height={300}>
                <PieChart>
                  <Pie
                    data={departmentData}
                    cx="50%"
                    cy="50%"
                    labelLine={false}
                    label={(entry) => entry.name}
                    outerRadius={80}
                    fill="#8884d8"
                    dataKey="value"
                  >
                    {departmentData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
          
          {/* Popular Searches and Notifications */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h3 className="text-lg font-semibold text-gray-800 mb-4">Popular Searches</h3>
              <div className="space-y-3">
                {popularSearches.map((search, index) => (
                  <div key={index} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                    <div className="flex items-center gap-3">
                      <span className="text-blue-600 font-bold">#{index + 1}</span>
                      <span className="text-gray-700">{search.query}</span>
                    </div>
                    <span className="text-sm text-gray-500">{search.count} searches</span>
                  </div>
                ))}
              </div>
            </div>
            
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h3 className="text-lg font-semibold text-gray-800 mb-4">Recent Notifications</h3>
              <div className="space-y-3">
                {recentNotifications.map((notification) => (
                  <div key={notification.id} className="flex items-start gap-3 p-3 bg-gray-50 rounded-lg">
                    <Bell size={16} className="text-blue-600 mt-0.5" />
                    <div className="flex-1">
                      <p className="text-sm text-gray-700">{notification.message}</p>
                      <p className="text-xs text-gray-400 mt-1">
                        {new Date(notification.created_at).toLocaleDateString()}
                      </p>
                    </div>
                    {!notification.is_read && (
                      <span className="w-2 h-2 bg-blue-600 rounded-full"></span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
